describe('Locked-out Customer Login Error State', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display error message when logging in with locked-out user credentials', () => {
    cy.get('[data-test="username"]').type('locked_out_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    cy.get('[data-testid="error"]').should('be.visible');
    cy.get('[data-testid="error"]').should('contain', 'Sorry, this user has been locked out');
    cy.get('[data-test="login-container"]').should('contain', 'Login');
    cy.get('[data-test="login-credentials-container"]').should('be.visible');
    cy.get('[data-test="login-credentials"]').should('contain', 'Username');
    cy.get('[data-test="login-credentials"]').should('contain', 'Password');
    cy.get('#page_wrapper').should('contain', 'Login');
  });

  it('should not navigate away from login page when error occurs', () => {
    cy.get('[data-test="username"]').type('locked_out_user');
    cy.get('[data-test="password"]').type('wrong_password');

    cy.get('[data-test="login-button"]').click();

    cy.url().should('include', '/login');
    cy.get('[data-testid="error"]').should('be.visible');
    cy.get('[data-testid="error"]').should('contain', 'Sorry, this user has been locked out');
    cy.get('#page_wrapper').should('contain', 'Login');
    cy.get('[data-test="header-container"]').should('contain', 'Sauce Labs');
  });
});
